package net.officefloor.hq.app.claim;

/** A claim as the screen shows it: the amount with two decimals, the date as yyyy-MM-dd, the status by name,
 *  the number (null when it has none), the due fixed when it was settled (null while it is live),
 *  who opened it (null until it is opened), whether a statement binds it and the figure it binds it to
 *  (null when unbound or n/a). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        Integer number, String settledDue, String openedBy, boolean stated, String statedDue) {
    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber(),
                claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                claim.getOpenedBy(), claim.isStated(),
                claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString());
    }
}
package net.officefloor.hq.app.person;

/** A person as the screen shows it, with the version an edit form sends back, and their statements:
 *  how many were taken, the last one's due-total (null: none taken, or n/a) and date (null: none taken),
 *  whether they are retired and from when (null: not retired), and whether they are on hold. */
public record PersonResponse(long id, String name, String grade, long version, int statementCount,
        String statedTotal, String statementDate, boolean retired, String retiredFrom,
        boolean held) {
    public static PersonResponse from(Person person) {
        return new PersonResponse(person.getId(), person.getName(), person.getGrade(), person.getVersion(),
                person.getStatementCount(),
                person.getStatedTotal() == null ? null : person.getStatedTotal().toPlainString(),
                person.getStatementDate() == null ? null : person.getStatementDate().toString(),
                person.getRetiredFrom() != null,
                person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(),
                person.isHeld());
    }
}
