124	/** One claim: its fields, status and due, with its edit and status buttons. A refused status change,
125	 *  or editing a claim that is not a draft, shows the row's error, which the row's next action clears. */
126	function ClaimRow({ sheet, claim: c, pct, onEdit }: {
127	  sheet: string; claim: Claim; pct: string | undefined; onEdit: () => void;
128	}) {
129	  const queryClient = useQueryClient();
130	  const [user] = useCurrentUser();
131	  const by = `?user=${encodeURIComponent(user ?? '')}`;
132	  const period = periodOf(usePeriods(sheet), c.date);
133	  const floor = useFloor(sheet);
134	  const terms = useTerms(sheet);
135	  const today = useSheetToday(sheet);
136	  const change = useMutation({
137	    mutationFn: (action: string) => postJson<Claim>(`${sheetPath(sheet)}/claims/${c.id}/${action}${by}`, {}),
138	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
139	  });
140	  const [editRefused, setEditRefused] = useState(false);
141	
142	  return (
143	    <li data-testid={`claim-row-${c.id}`}>
144	      #<span data-testid="claim-number">{c.number ?? ''}</span>{' '}
145	      <span data-testid="claim-amount">{c.amount}</span>{' '}
146	      <span data-testid="claim-date">{c.date}</span>{' '}
147	      Period <span data-testid="claim-period">{period?.name ?? ''}</span>{' '}
148	      <span data-testid="claim-note">{c.note}</span>{' '}
149	      <span data-testid="claim-status">{c.status}</span>{' '}
150	      Opened by <span data-testid="claim-opened-by">{c.openedBy ?? ''}</span>{' '}
151	      Due <span data-testid="claim-due">{claimDue(c, pct, floor)}</span>{' '}
152	      Due by <span data-testid="claim-due-by">{dueBy(c, terms)}</span>{' '}
